import numpy as np
from collections import deque
A=np.load('source_pixels.npz')['rgb']
# masks and comps helper
conds={
'red':lambda im:(im[:,:,0]>im[:,:,1]*1.15)&(im[:,:,0]>im[:,:,2]*1.15)&(im[:,:,0]>100),
'red_loose':lambda im:(im[:,:,0]>im[:,:,1]+15)&(im[:,:,0]>im[:,:,2]+12)&(im[:,:,0]>90),
'blue':lambda im:(im[:,:,2]>im[:,:,0]*1.1)&(im[:,:,2]>im[:,:,1]*1.05)&(im[:,:,2]>90),
'dark':lambda im:im.mean(2)<100,
'green':lambda im:(im[:,:,1]>im[:,:,0]*1.1)&(im[:,:,1]>im[:,:,2]*1.1),
}
def comps(mask,minn=3):
 h,w=mask.shape; seen=np.zeros_like(mask); out=[]
 for y,x in zip(*np.where(mask)):
  if seen[y,x]:continue
  st=[(y,x)];seen[y,x]=1;pts=[]
  while st:
   yy,xx=st.pop();pts.append((yy,xx))
   for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
    y2,x2=yy+dy,xx+dx
    if 0<=y2<h and 0<=x2<w and mask[y2,x2] and not seen[y2,x2]:seen[y2,x2]=1;st.append((y2,x2))
  if len(pts)>=minn:
   yy=np.array([p[0] for p in pts]);xx=np.array([p[1] for p in pts])
   out.append((len(pts),round(xx.mean(),1),round(yy.mean(),1),int(xx.min()),int(yy.min()),int(xx.max()),int(yy.max())))
 return sorted(out,reverse=True)
for name,fn in conds.items():
 print('\\n###',name)
 for t in [0,1,2,3,5,8,12,16,20,24,30,36,42,48,60,72,84,95]:
  cs=comps(fn(A[t]),8)[:8]
  print(t,cs)
