import numpy as np
A=np.load('source_pixels.npz')['rgb'].astype(int)
# classify high chroma components 8conn & print comps in y55:90, exclude giant component >100 area
def cc(mask):
 H,W=mask.shape; seen=np.zeros_like(mask); out=[]
 for y,x in zip(*np.where(mask)):
  if seen[y,x]:continue
  q=[(y,x)];seen[y,x]=1;p=[]
  while q:
   yy,xx=q.pop();p.append((yy,xx))
   for dy in [-1,0,1]:
    for dx in [-1,0,1]:
     y2=yy+dy;x2=xx+dx
     if 0<=y2<H and 0<=x2<W and mask[y2,x2] and not seen[y2,x2]:seen[y2,x2]=1;q.append((y2,x2))
  if len(p)>=4:
   yy=np.array([v[0] for v in p]);xx=np.array([v[1] for v in p]);out.append((len(p),xx.mean(),yy.mean(),xx.min(),yy.min(),xx.max(),yy.max()))
 return sorted(out,reverse=True)
for t in range(96):
 im=A[t];r,g,b=np.moveaxis(im,2,0)
 red=(r-g>35)&(r-b>30)&(r>100)
 yellow=(r-b>22)&(g-b>15)&(r>120)&(g>100)&~red
 cyan=(b-r>18)&(g-r>8)&(b>100)
 cr=[v for v in cc(red) if v[0]<200]
 cy=[v for v in cc(yellow) if v[0]<200]
 if t%2==0:
  print(f'{t:02d} R',[(round(x[1],1),round(x[2],1),x[0],x[3:]) for x in cr[:3]],'Y',[(round(x[1],1),round(x[2],1),x[0],x[3:]) for x in cy[:4]])
